/**
 * cusps.js — a certificate that Γ ⊂ PGL₂(K) is S-arithmetic, for any number field K, from the
 * unipotents of Γ at one cusp. S is the set of primes of K where Γ is unbounded, O_S the S-integers,
 * and O_S^× must be infinite: always when S ≠ ∅, and when S = ∅ unless K is ℚ or imaginary quadratic
 * (and there Γ is discrete at ∞ by integrality anyway).
 *
 * Theorem (Vaserstein 1972). If O_S^× is infinite, then for every nonzero ideal 𝔮 ⊂ O_S the group
 * E(𝔮) generated by (1 x; 0 1) and (1 0; x 1), x ∈ 𝔮, has finite index in SL₂(O_S).
 * Theorem (Benoist–Oh 2010, a case of Selberg's conjecture; Benoist–Miquel 2020 in general). A
 * discrete Zariski-dense subgroup of ∏_{v ∈ S∪∞} SL₂(K_v) (at least two factors) that meets a
 * horospherical subgroup in a lattice is arithmetic.
 *
 * The S = ∅ case first:
 *
 * The certificate: a cusp c ∈ P¹(K) whose unipotent stabilizer U_c ∩ Γ has ℤ-rank [K : ℚ]. Then for
 * any γ ∈ Γ with γc ≠ c (Γ is not elementary), conjugate by h ∈ PGL₂(K) taking c ↦ ∞ and γc ↦ 0:
 * hΓh⁻¹ contains (1 x; 0 1) for x in a full lattice L ⊂ K and (1 0; x 1) for x in a full lattice L′,
 * and both lattices contain N·O for an integer N. So hΓh⁻¹ ⊇ E(N·O), of finite index in SL₂(O):
 * Γ contains a lattice of ∏_{v|∞} PGL₂(K_v). It is discrete there (bounded at every prime), so it
 * is a lattice itself, commensurable with PGL₂(O): arithmetic. (Benoist–Oh, discreteness criterion
 * for subgroups of products of SL₂, gives the same from the lattice at one cusp.)
 *
 * With S ≠ ∅ the unipotents of SL₂(O_S) at a cusp form O_S, which is not finitely generated, so a
 * rank is not enough. A parabolic τ and multipliers α₁, …, α_r of elements fixing the cusp give
 * U_c ∩ Γ ⊇ R·τ with R = ℤ[α₁^{±1}, …, α_r^{±1}] ⊂ O_S. When some αᵢ generates K and every prime of S
 * divides some αᵢ (they are S-units, so their supports lie in S), the integral closure of R in K is
 * O_S, a finite R-module; the conductor contains some x ≠ 0, and x·O_S ⊆ R, so R has finite index
 * in O_S (O_S/xO_S is finite). Then U_c ∩ Γ contains a finite-index subgroup of the fractional ideal
 * O_S·τ, and the argument above (conjugating c to ∞ and γc to 0) gives E(𝔮) ⊆ hΓh⁻¹: Γ contains a
 * lattice of ∏_{v∈S∪∞} PGL₂(K_v), and being discrete there it is S-arithmetic. Valuations at the
 * primes of S are exact (ringEngine.js: the maximal order, primes above p, valuations).
 *
 * The rank. Words of Γ are enumerated. A parabolic g fixing c, conjugated by h_c (c ↦ ∞), is a
 * translation by τ ∈ K; an element fixing c that is not parabolic has a multiplier α = λ₁/λ₂, a
 * unit, and hᵏ g h⁻ᵏ translates by αᵏτ. So U_c ∩ Γ contains ℤ[α]·τ for every such pair, and the
 * rank is that of the ℚ-span of {αᵏ τ}, by exact linear algebra. Everything is exact in ℤ[w]; the
 * floating-point values at one embedding only suggest which elements fix which cusp.
 */

const babs = (x) => (x < 0n ? -x : x);
const bgcd = (a, b) => { a = babs(a); b = babs(b); while (b) [a, b] = [b, a % b]; return a; };

/** ℤ[w] and ℚ(w) for a monic integer polynomial P (low → high). Elements: BigInt coefficient vectors. */
export function field(P) {
    const d = P.length - 1;
    const reduce = (r) => {
        r = r.slice();
        for (let k = r.length - 1; k >= d; k--) { const c = r[k]; if (c === 0n) continue; for (let j = 0; j < d; j++) r[k - d + j] -= c * P[j]; r[k] = 0n; }
        while (r.length < d) r.push(0n);
        return r.slice(0, d);
    };
    const mul = (a, b) => { const r = Array(2 * d - 1).fill(0n); for (let i = 0; i < d; i++) if (a[i]) for (let j = 0; j < d; j++) r[i + j] += a[i] * b[j]; return reduce(r); };
    const add = (a, b) => a.map((x, i) => x + b[i]);
    const sub = (a, b) => a.map((x, i) => x - b[i]);
    const scale = (a, k) => a.map((x) => x * k);
    const isZero = (a) => a.every((x) => x === 0n);
    const zero = Array(d).fill(0n), one = zero.map((_, i) => (i === 0 ? 1n : 0n)), wv = zero.map((_, i) => (i === 1 ? 1n : 0n));
    /** the matrix of multiplication by a (columns: a·w^j) */
    const mulMatrix = (a) => { const cols = []; let x = one; for (let j = 0; j < d; j++) { cols.push(mul(a, x)); x = mul(x, wv); } return cols; };
    /** x / y as a rational vector [nums, den] (solve over ℚ by fraction-free elimination) */
    const divide = (x, y) => {
        const C = mulMatrix(y);
        const M = Array.from({ length: d }, (_, r) => C.map((c) => c[r]).concat([x[r]]));
        // Bareiss
        let prev = 1n;
        for (let k = 0; k < d; k++) {
            let p = k; while (p < d && M[p][k] === 0n) p++;
            if (p === d) throw new Error('divide by zero');
            [M[k], M[p]] = [M[p], M[k]];
            for (let i = k + 1; i < d; i++) {
                for (let j = k + 1; j <= d; j++) M[i][j] = (M[i][j] * M[k][k] - M[i][k] * M[k][j]) / prev;
                M[i][k] = 0n;
            }
            prev = M[k][k];
        }
        // back substitution with rationals [n, m]
        const q = Array(d);
        for (let i = d - 1; i >= 0; i--) {
            let n = M[i][d], m = 1n;
            for (let j = i + 1; j < d; j++) { const [qn, qm] = q[j]; n = n * qm - M[i][j] * qn * m; m *= qm; }
            const den = M[i][i] * m, g = bgcd(n, den) || 1n;
            q[i] = den < 0n ? [-n / g, -den / g] : [n / g, den / g];
        }
        const L = q.reduce((l, [, m]) => (l / bgcd(l, m)) * m, 1n);
        return { num: q.map(([n, m]) => n * (L / m)), den: L };
    };
    return { d, mul, add, sub, scale, isZero, zero, one, w: wv, divide };
}

/** ringEngine text c₀ + c₁w + c₂w² + … (rational coefficients) as [nums, den], or null. */
export function parsePoly(src, d) {
    const s = String(src).replace(/\s+/g, '').replace(/\*/g, '').replace(/\^\{(\d+)\}/g, '^$1');
    const terms = s.match(/[+-]?[^+-]+/g);
    if (!terms) return null;
    const num = Array(d).fill(0n);
    let den = 1n;
    for (let t of terms) {
        let sign = 1n;
        if (t[0] === '+') t = t.slice(1); else if (t[0] === '-') { sign = -1n; t = t.slice(1); }
        const m = /^(?:\(?(\d+)(?:\/(\d+))?\)?)?(w(?:\^(\d+))?)?$/.exec(t);
        if (!m || (!m[1] && !m[3])) return null;
        const k = m[3] ? (m[4] ? Number(m[4]) : 1) : 0;
        if (k >= d) return null;
        const a = BigInt(m[1] || '1'), b = BigInt(m[2] || '1');
        // num/den + sign·a/b
        const L = (den / bgcd(den, b)) * b;
        for (let i = 0; i < d; i++) num[i] *= L / den;
        num[k] += sign * a * (L / b);
        den = L;
    }
    return { num, den };
}

/** Rank over ℚ of integer vectors (fraction-free elimination). */
function rankQ(rows) {
    const M = rows.map((r) => r.slice());
    let rank = 0;
    const n = M.length ? M[0].length : 0;
    for (let c = 0; c < n && rank < M.length; c++) {
        let p = rank; while (p < M.length && M[p][c] === 0n) p++;
        if (p === M.length) continue;
        [M[rank], M[p]] = [M[p], M[rank]];
        for (let i = rank + 1; i < M.length; i++) {
            if (M[i][c] === 0n) continue;
            const a = M[rank][c], b = M[i][c];
            M[i] = M[i].map((x, j) => x * a - M[rank][j] * b);
            const g = M[i].reduce((s, x) => bgcd(s, x), 0n);
            if (g > 1n) M[i] = M[i].map((x) => x / g);
        }
        rank++;
    }
    return rank;
}

/**
 * Search for the certificate. gens: rows of ringEngine text; poly: the minimal polynomial of w as
 * integers low → high; root: a complex root, for the floating-point hints. Returns
 * { found: true, cusp, rank, d, parabolic, other, alpha } or { found: false, reason, elements, cusps }.
 */
export function cuspCertificate(gens, poly, root, opts = {}) {
    const P = poly.map(BigInt), K = field(P);
    const G = integralGens(K, gens);
    if (!G) return { found: false, reason: 'an entry could not be read' };
    return certificateFor(K, G, root, { ...opts, poly: P });
}

/**
 * The same for the subgroup generated by words in the generators (letters ±(i+1)): for the
 * elements of Γ fixing the standard vertex of the trees, when Γ is unbounded at some primes. Then
 * Γ_o ⊂ PGL₂(O_K), and a full lattice of unipotents at a cusp of ⟨words⟩ makes it a lattice there.
 */
export function cuspCertificateWords(gens, poly, words, root, opts = {}) {
    const P = poly.map(BigInt), K = field(P);
    const G = integralGens(K, gens);
    if (!G) return { found: false, reason: 'an entry could not be read' };
    const { mm, adj, prim } = matOps(K);
    const H = words.map((w) => { let M = [K.one, K.zero, K.zero, K.one]; for (const x of w) M = prim(mm(M, x > 0 ? G[x - 1] : adj(G[-x - 1]))); return M; });
    // the elements fix the standard vertex of every tree: bounded everywhere, S = ∅
    return certificateFor(K, H, root, { ...opts, poly: P, S: [] });
}

/**
 * The same for Γ itself, with a pool of its elements given as words (FlashBeam's lowest elements):
 * in S-arithmetic groups the parabolics are long words, which breadth-first search does not reach.
 * S is computed from the generators. The pool is used alongside a short breadth-first search.
 */
export function cuspCertificatePool(gens, poly, words, root, opts = {}) {
    const P = poly.map(BigInt), K = field(P);
    const G = integralGens(K, gens);
    if (!G) return { found: false, reason: 'an entry could not be read' };
    const { mm, adj, prim } = matOps(K);
    const seen = new Set(), pool = [];
    for (const w of words) {
        const k = w.join(',');
        if (!w.length || seen.has(k)) continue;
        seen.add(k);
        let M = [K.one, K.zero, K.zero, K.one];
        for (const x of w) M = prim(mm(M, x > 0 ? G[x - 1] : adj(G[-x - 1])));
        pool.push({ M, word: w });
    }
    return certificateFor(K, G, root, { ...opts, poly: P, pool });
}

/** Generators (rows of ringEngine text) as integral matrices with coprime coefficients, or null. */
/**
 * The first of the words whose element has infinite order, or null. An element g of finite order
 * has x = tr²(g)/det(g) = 2 + ζ + ζ⁻¹ for a root of unity ζ, in [0, 4] at every embedding, and
 * x = 4 only for g = 1. So g has infinite order if x = 4 with g ≠ 1 (exact: g is parabolic), or if
 * |σ(x) − 2| > 2 at some embedding σ: checked in floating point with a bound on the rounding,
 * and on the error of the computed roots of poly.
 * Returns { index, word, why: 'parabolic' | 'loxodromic' }.
 */
export function infiniteOrderWord(gens, poly, words, opts = {}) {
    const P = poly.map(BigInt), K = field(P);
    const G = integralGens(K, gens);
    if (!G) return null;
    const { mm, adj, prim } = matOps(K);
    const roots = complexRoots(P);
    const n = Math.min(words.length, opts.maxWords ?? 400);
    for (let i = 0; i < n; i++) {
        const w = words[i];
        let M = [K.one, K.zero, K.zero, K.one];
        for (const x of w) M = prim(mm(M, x > 0 ? G[x - 1] : adj(G[-x - 1])));
        if (K.isZero(M[1]) && K.isZero(M[2]) && K.isZero(K.sub(M[0], M[3]))) continue;
        const tr = K.add(M[0], M[3]), t2 = K.mul(tr, tr), det = K.sub(K.mul(M[0], M[3]), K.mul(M[1], M[2]));
        if (K.isZero(K.sub(t2, K.scale(det, 4n)))) return { index: i, word: w, why: 'parabolic' };
        if (roots.some((r) => outsideDisc(t2, det, r))) return { index: i, word: w, why: 'loxodromic' };
    }
    return null;
}

/** |σ(a/b) − 2| > 2 at the root r ± r.err, proved with the rounding bounded (a, b: integral coordinates). */
function outsideDisc(a, b, r) {
    let top = 0;
    for (const c of a.concat(b)) { const t = c < 0n ? -c : c; const l = t.toString(2).length; if (l > top) top = l; }
    const s = BigInt(Math.max(0, top - 900));
    const R = Math.hypot(r.re, r.im), dr = r.err;
    const ev = (u) => {
        // σ(u >> s) and a bound on its error: rounding of each term, the shift, and the root's error
        let re = 0, im = 0, pre = 1, pim = 0, err = 0, mag = 1;
        for (let i = 0; i < u.length; i++) {
            const c = Number(u[i] >> s), ac = Math.abs(c);
            re += c * pre; im += c * pim;
            err += (ac * 1e-14 * (u.length + 2) + (s ? 1 : 0)) * mag + (i ? ac * i * Math.pow(R + dr, i - 1) * dr : 0);
            [pre, pim] = [pre * r.re - pim * r.im, pre * r.im + pim * r.re];
            mag *= R;
        }
        return { re, im, err };
    };
    const A = ev(a), B = ev(b);
    const absB = Math.hypot(B.re, B.im);
    if (!(absB > B.err)) return false;
    const num = Math.hypot(A.re - 2 * B.re, A.im - 2 * B.im) - A.err - 2 * B.err;
    return num > 2 * (absB + B.err) * (1 + 1e-9);
}

/** The complex roots of an integer polynomial (low → high), by Durand–Kerner, each with an error bound. */
function complexRoots(P) {
    const d = P.length - 1;
    if (d < 1) return [];
    const lead = Number(P[d]), c = P.map((x) => Number(x) / lead);
    const f = (z) => { let re = 0, im = 0; for (let i = d; i >= 0; i--) { [re, im] = [re * z.re - im * z.im + c[i], re * z.im + im * z.re]; } return { re, im }; };
    let zs = Array.from({ length: d }, (_, k) => ({ re: Math.cos(0.4 + 2 * Math.PI * k / d) * 1.1, im: Math.sin(0.4 + 2 * Math.PI * k / d) * 1.1 }));
    for (let it = 0; it < 500; it++) {
        let moved = 0;
        zs = zs.map((z, k) => {
            let dre = 1, dim = 0;
            zs.forEach((y, j) => { if (j !== k) { const ar = z.re - y.re, ai = z.im - y.im; [dre, dim] = [dre * ar - dim * ai, dre * ai + dim * ar]; } });
            const v = f(z), q = dre * dre + dim * dim;
            const step = { re: (v.re * dre + v.im * dim) / q, im: (v.im * dre - v.re * dim) / q };
            moved = Math.max(moved, Math.hypot(step.re, step.im));
            return { re: z.re - step.re, im: z.im - step.im };
        });
        if (moved < 1e-15) break;
    }
    // a root lies within d·|f(z)/∏(z − y)| of z (the Durand–Kerner step, by Gerschgorin-type bounds): kept generous
    return zs.map((z, k) => {
        let dre = 1, dim = 0;
        zs.forEach((y, j) => { if (j !== k) { const ar = z.re - y.re, ai = z.im - y.im; [dre, dim] = [dre * ar - dim * ai, dre * ai + dim * ar]; } });
        const v = f(z);
        const e = d * Math.hypot(v.re, v.im) / Math.hypot(dre, dim);
        return { re: z.re, im: z.im, err: Math.max(1e-12 * (1 + Math.hypot(z.re, z.im)), 10 * e) };
    });
}

function integralGens(K, gens) {
    const d = K.d, G = [];
    for (const row of gens) {
        const q = row.map((e) => parsePoly(e, d));
        if (q.some((x) => !x)) return null;
        const L = q.reduce((l, e) => (l / bgcd(l, e.den)) * e.den, 1n);
        let M = q.map((e) => e.num.map((x) => x * (L / e.den)));
        const g = M.flat().reduce((s, x) => bgcd(s, x), 0n);
        M = M.map((e) => e.map((x) => x / g));
        G.push(M);
    }
    return G;
}
function matOps(K) {
    const mm = (A, B) => [K.add(K.mul(A[0], B[0]), K.mul(A[1], B[2])), K.add(K.mul(A[0], B[1]), K.mul(A[1], B[3])), K.add(K.mul(A[2], B[0]), K.mul(A[3], B[2])), K.add(K.mul(A[2], B[1]), K.mul(A[3], B[3]))];
    const adj = (A) => [A[3], K.scale(A[1], -1n), K.scale(A[2], -1n), A[0]];
    const prim = (A) => { const g = A.flat().reduce((s, x) => bgcd(s, x), 0n); return g > 1n ? A.map((e) => e.map((x) => x / g)) : A; };
    return { mm, adj, prim };
}

/** ringEngine's maximal order of ℚ(w), for valuations (null when the engine is not loaded). */
function ringOf(poly) {
    const RE = globalThis.NumberRingEngine;
    if (!RE || !RE._internal) return null;
    const X = RE._internal;
    const M = X.maximalOrderFor(poly.map(BigInt));
    const sv = (q) => X.toSV(M.O.toCoords(q.num.map((n) => new X.Rat(n, q.den))));
    return { val: (q, pr) => X.valuationSV(M.O, pr, sv(q)), above: (p) => X.primesAbove(M.O, BigInt(p)) };
}
/** N_{K/ℚ}(x) for x ∈ ℤ[w]: the determinant of multiplication by x. */
function normOf(K, x) {
    const d = K.d;
    const cols = [];
    let y = x;
    for (let j = 0; j < d; j++) { cols.push(y); y = K.mul(y, K.w); }
    const M = Array.from({ length: d }, (_, r) => cols.map((c) => c[r]));
    const det = (A) => (A.length === 1 ? A[0][0] : A[0].reduce((s, a, j) => s + (j % 2 ? -1n : 1n) * a * det(A.slice(1).map((row) => row.filter((_, k) => k !== j))), 0n));
    return det(M);
}
function primeFactors(n) {
    n = n < 0n ? -n : n;
    const out = [];
    for (let p = 2n; p * p <= n; p++) if (n % p === 0n) { out.push(p); while (n % p === 0n) n /= p; }
    if (n > 1n) out.push(n);
    return out;
}
/**
 * The primes of K where Γ = ⟨G⟩ is unbounded: among the primes dividing a determinant, those where
 * tr²/det of a generator or of a product of two has negative valuation (for two generators the
 * traces of a, b, ab generate the trace ring; integral traces mean a bounded group).
 * Returns [{ p, pr }] or null without ringEngine.
 */
function unboundedPrimes(K, G, ring) {
    const mm = (A, B) => [K.add(K.mul(A[0], B[0]), K.mul(A[1], B[2])), K.add(K.mul(A[0], B[1]), K.mul(A[1], B[3])), K.add(K.mul(A[2], B[0]), K.mul(A[3], B[2])), K.add(K.mul(A[2], B[1]), K.mul(A[3], B[3]))];
    const adj = (A) => [A[3], K.scale(A[1], -1n), K.scale(A[2], -1n), A[0]];
    const det = (A) => K.sub(K.mul(A[0], A[3]), K.mul(A[1], A[2]));
    const words = G.slice();
    for (let i = 0; i < G.length; i++) for (let j = i + 1; j < G.length; j++) words.push(mm(G[i], G[j]), mm(G[i], adj(G[j])));
    const taus = words.map((A) => { const t = K.add(A[0], A[3]); return K.divide(K.mul(t, t), det(A)); });
    const ps = new Set();
    for (const g of G) for (const p of primeFactors(normOf(K, det(g)))) ps.add(p);
    const S = [];
    for (const p of [...ps].sort((a, b) => (a < b ? -1 : 1))) for (const pr of ring.above(p)) {
        if (taus.some((t) => !K.isZero(t.num) && ring.val(t, pr) < 0)) S.push({ p, pr });
    }
    return S;
}

function certificateFor(K, G, root, { maxElements = 40000, seconds = 10, S: Sgiven = null, poly = null, pool = null, collisions = true } = {}) {
    const t0 = Date.now(), d = K.d;
    // O^× is infinite unless K is ℚ or imaginary quadratic
    const P2 = poly ? poly.map(BigInt) : null;
    const unitsInfinite = d >= 3 || (d === 2 && !!P2 && P2[1] * P2[1] - 4n * P2[0] * P2[2] > 0n);
    // the primes where Γ is unbounded (given, e.g. [] for a vertex stabilizer, or computed)
    const ring = poly ? ringOf(poly) : null;
    let S = Sgiven;
    if (!S) {
        if (!ring) return { found: false, reason: 'ringEngine is not loaded: the primes where Γ is unbounded are unknown' };
        S = unboundedPrimes(K, G, ring);
    }
    if (S.length && !ring) return { found: false, reason: 'ringEngine is not loaded' };
    const mm = (A, B) => [K.add(K.mul(A[0], B[0]), K.mul(A[1], B[2])), K.add(K.mul(A[0], B[1]), K.mul(A[1], B[3])), K.add(K.mul(A[2], B[0]), K.mul(A[3], B[2])), K.add(K.mul(A[2], B[1]), K.mul(A[3], B[3]))];
    const adj = (A) => [A[3], K.scale(A[1], -1n), K.scale(A[2], -1n), A[0]];
    const prim = (A) => { const g = A.flat().reduce((s, x) => bgcd(s, x), 0n); return g > 1n ? A.map((e) => e.map((x) => x / g)) : A; };
    const letters = G.flatMap((g) => [g, adj(g)]);
    // floating point at the root, for hints
    const ev = (a) => { let re = 0, im = 0; for (let k = a.length - 1; k >= 0; k--) { const r = re * root.re - im * root.im + Number(a[k]), i = re * root.im + im * root.re; re = r; im = i; } return { re, im }; };
    const cdiv = (a, b) => { const q = b.re * b.re + b.im * b.im; return { re: (a.re * b.re + a.im * b.im) / q, im: (a.im * b.re - a.re * b.im) / q }; };
    const ckey = (z) => (z === null ? 'inf' : `${Math.round(z.re * 1e6)},${Math.round(z.im * 1e6)}`);
    // enumerate reduced words breadth first, exact matrices, deduplicated by their floating-point images
    const seenKey = new Set();
    const bitsOf = (A) => { let top = 0; for (const e of A) for (const x of e) { const l = (x < 0n ? -x : x).toString(2).length; if (l > top) top = l; } return top; };
    const keyOf = (A) => {
        // projective: the entries scaled down together stay in floating range
        const top = bitsOf(A), sh = BigInt(Math.max(0, top - 600));
        const v = (sh ? A.map((e) => e.map((x) => x >> sh)) : A).map(ev);
        const k = v.findIndex((z) => Math.hypot(z.re, z.im) > 1e-9);
        if (k < 0 || v.some((z) => !Number.isFinite(z.re) || !Number.isFinite(z.im))) return 'x:' + A.map((e) => e.join(',')).join(';');   // out of floating range: an exact key
        return v.map((z) => cdiv(z, v[k])).map((z) => `${z.re.toPrecision(12)},${z.im.toPrecision(12)}`).join(';');
    };
    let frontier = [{ M: [K.one, K.zero, K.zero, K.one], last: -1, word: [] }];
    const elements = [];
    // a memory budget too: the letters may be large matrices (elements of a vertex stabilizer), and
    // their products grow
    let bitsUsed = 0;
    const bitBudget = 2.4e9;
    while (frontier.length && elements.length < maxElements && bitsUsed < bitBudget && Date.now() - t0 < 1000 * seconds) {
        const next = [];
        for (const x of frontier) {
            for (let i = 0; i < letters.length; i++) {
                if (x.last >= 0 && (i ^ 1) === x.last) continue;
                const M = prim(mm(x.M, letters[i]));
                const k = keyOf(M);
                if (seenKey.has(k)) continue;
                seenKey.add(k);
                const word = x.word.concat(i % 2 ? -(i >> 1) - 1 : (i >> 1) + 1);
                elements.push({ M, word });
                next.push({ M, last: i, word });
                bitsUsed += 4 * d * bitsOf(M) + 64 * word.length;
                if (elements.length >= maxElements || bitsUsed >= bitBudget) break;
            }
            if (elements.length >= maxElements || bitsUsed >= bitBudget) break;
        }
        frontier = next;
    }
    if (pool) for (const e of pool) { const k = keyOf(e.M); if (!seenKey.has(k)) { seenKey.add(k); elements.push(e); } }
    // parabolics: tr² = 4 det, not scalar; their fixed points are the cusps
    const cusps = new Map();          // exact key → { x, y, z (float), trans: [], mult: [] }
    const exactKey = (x, y) => { if (K.isZero(y)) return 'inf'; const q = K.divide(x, y); return q.num.join(',') + '/' + q.den; };
    const tr = (A) => K.add(A[0], A[3]);
    const det = (A) => K.sub(K.mul(A[0], A[3]), K.mul(A[1], A[2]));
    const isScalar = (A) => K.isZero(A[1]) && K.isZero(A[2]) && K.isZero(K.sub(A[0], A[3]));
    const byFloat = new Map();
    for (const e of elements) {
        const A = e.M;
        if (isScalar(A)) continue;
        const t = tr(A), D = det(A);
        if (!K.isZero(K.sub(K.mul(t, t), K.scale(D, 4n)))) continue;
        // fixed point [a − d : 2c] (or ∞)
        const x = K.isZero(A[2]) ? K.one : K.sub(A[0], A[3]), y = K.isZero(A[2]) ? K.zero : K.scale(A[2], 2n);
        const k = exactKey(x, y);
        if (!cusps.has(k)) {
            const z = K.isZero(y) ? null : cdiv(ev(x), ev(y));
            const c = { x, y, z, key: k, trans: [], mult: [], words: [] };
            cusps.set(k, c);
            const fk = ckey(z);
            if (!byFloat.has(fk)) byFloat.set(fk, []);
            byFloat.get(fk).push(c);
        }
        cusps.get(k).words.push({ word: e.word, M: A, parabolic: true });
    }
    // the other elements fixing a cusp: their fixed points in floating point, then checked exactly
    const fixedFloat = (A) => {
        const a = ev(A[0]), b = ev(A[1]), c = ev(A[2]), dd = ev(A[3]);
        if (Math.hypot(c.re, c.im) < 1e-12) return [null, cdiv(b, { re: dd.re - a.re, im: dd.im - a.im })];
        // c z² + (d − a) z − b = 0
        const B = { re: dd.re - a.re, im: dd.im - a.im };
        const disc = { re: B.re * B.re - B.im * B.im + 4 * (c.re * b.re - c.im * b.im), im: 2 * B.re * B.im + 4 * (c.re * b.im + c.im * b.re) };
        const r = Math.hypot(disc.re, disc.im), sq = { re: Math.sqrt((r + disc.re) / 2), im: Math.sign(disc.im || 1) * Math.sqrt(Math.max(0, (r - disc.re) / 2)) };
        const two = { re: 2 * c.re, im: 2 * c.im };
        return [cdiv({ re: -B.re + sq.re, im: -B.im + sq.im }, two), cdiv({ re: -B.re - sq.re, im: -B.im - sq.im }, two)];
    };
    // parabolics from commutators: two elements with a common fixed point and different multipliers
    // (a Borel subgroup) have a unipotent commutator, fixing that point; elements are grouped by their
    // fixed points in floating point, and every commutator is checked exactly
    {
        const byPoint = new Map();
        for (const e of elements) {
            const A = e.M;
            if (isScalar(A)) continue;
            for (const z of fixedFloat(A)) {
                if (z && !(Number.isFinite(z.re) && Number.isFinite(z.im))) continue;
                const k = ckey(z);
                if (!byPoint.has(k)) byPoint.set(k, []);
                const L = byPoint.get(k);
                if (L.length < 12) L.push(e);
            }
        }
        const inv = (w) => w.slice().reverse().map((x) => -x);
        let added = 0;
        for (const L of byPoint.values()) {
            if (L.length < 2 || added > 400) continue;
            for (let j = 1; j < L.length; j++) {
                const A = L[0].M, B = L[j].M;
                const C = prim(mm(mm(A, B), mm(adj(A), adj(B))));
                if (isScalar(C)) continue;
                const t = tr(C), D = det(C);
                if (!K.isZero(K.sub(K.mul(t, t), K.scale(D, 4n)))) continue;
                const x = K.isZero(C[2]) ? K.one : K.sub(C[0], C[3]), y = K.isZero(C[2]) ? K.zero : K.scale(C[2], 2n);
                const k = exactKey(x, y);
                if (!cusps.has(k)) {
                    const z = K.isZero(y) ? null : cdiv(ev(x), ev(y));
                    const c = { x, y, z, key: k, words: [] };
                    cusps.set(k, c);
                    const fk = ckey(z);
                    if (!byFloat.has(fk)) byFloat.set(fk, []);
                    byFloat.get(fk).push(c);
                }
                cusps.get(k).words.push({ word: L[0].word.concat(L[j].word, inv(L[0].word), inv(L[j].word)), M: C, parabolic: true });
                added++;
                break;
            }
        }
    }
    if (!cusps.size) return { found: false, S: S.map((pl) => `${pl.p}`), reason: 'no parabolic element found', elements: elements.length, cusps: 0, ms: Date.now() - t0 };
    // conjugation by h_c = (0 1; −y x): c = [x : y] ↦ ∞ (h = 1 when c = ∞)
    const conjAt = (c, A) => {
        if (K.isZero(c.y)) return A;
        const h = [K.zero, K.one, K.scale(c.y, -1n), c.x], hi = adj(h);
        return mm(mm(h, A), hi);
    };
    const fixes = (c, A) => K.isZero(K.sub(K.mul(K.add(K.mul(A[0], c.x), K.mul(A[1], c.y)), c.y), K.mul(K.add(K.mul(A[2], c.x), K.mul(A[3], c.y)), c.x)));
    for (const e of elements) {
        const A = e.M;
        const t = tr(A), D = det(A);
        if (K.isZero(K.sub(K.mul(t, t), K.scale(D, 4n)))) continue;          // parabolic: done above
        for (const z of fixedFloat(A)) {
            for (const c of byFloat.get(ckey(z)) || []) if (fixes(c, A)) c.words.push({ word: e.word, M: A, parabolic: false });
        }
    }
    // more of each cusp's stabilizer, by collisions of its orbit modulo a known parabolic u at c: if
    // e(c) = u^s f(c) then f⁻¹u^{−s}e fixes c. In the frame h_c (c ↦ ∞), u is z ↦ z + τ, and the
    // images e(c) are keyed by (e(c)/τ) mod ℤ, exactly; every element found is checked to fix c.
    if (collisions) {
        const inv = (w) => w.slice().reverse().map((x) => -x);
        const powW = (w, n) => { const b = n < 0 ? inv(w) : w; const out = []; for (let i = 0; i < Math.abs(n); i++) out.push(...b); return out; };
        let budget = 2000;
        for (const c of [...cusps.values()].slice(0, 8)) {
            const par = c.words.find((it) => it.parabolic);
            if (!par || budget <= 0) continue;
            const B = conjAt(c, par.M);
            const tau = K.divide(B[1], B[3]);                      // u: z ↦ z + τ in the frame
            if (K.isZero(tau.num)) continue;
            const tauEl = { num: tau.num, den: tau.den };
            const table = new Map();
            let found = 0;
            for (const e of elements) {
                if (Date.now() - t0 > 1000 * seconds * 1.5 || budget <= 0) break;
                // e(c) in the frame: h_c·e·(c) = (h_c e h_c⁻¹)(∞)
                const E = conjAt(c, e.M);
                if (K.isZero(E[2])) continue;                       // e fixes c: found above
                const p = K.divide(E[0], E[2]);                     // the point, as [num, den]
                // r = p/τ = (p.num·τ.den) / (p.den·τ.num): exact, as a rational vector
                const r = K.divide(K.scale(p.num, tauEl.den), K.scale(tauEl.num, p.den));
                const c0 = r.num[0];
                const k0 = (c0 >= 0n ? c0 : c0 - r.den + 1n) / r.den;           // ⌊r₀⌋
                const key = [c0 - k0 * r.den].concat(r.num.slice(1)).join(',') + '/' + r.den;
                const hit = table.get(key);
                if (!hit) { table.set(key, { e, k: k0 }); continue; }
                const s = Number(k0 - hit.k);
                if (Math.abs(s) > 64) continue;
                const word = inv(hit.e.word).concat(powW(par.word, -s), e.word);
                let M = [K.one, K.zero, K.zero, K.one];
                for (const x of word) M = prim(mm(M, x > 0 ? G[x - 1] : adj(G[-x - 1])));
                if (isScalar(M) || !fixes(c, M)) continue;
                const t2 = tr(M), D2 = det(M);
                c.words.push({ word, M, parabolic: K.isZero(K.sub(K.mul(t2, t2), K.scale(D2, 4n))) });
                found++; budget--;
                if (found > 400) break;
            }
            c.collisions = found;
        }
    }
    // the rank at each cusp (S = ∅), or a parabolic with multipliers that generate K and cover S
    const generatesK = (q) => { const vs = []; let cur = { num: K.one }; for (let k = 0; k < d; k++) { vs.push(cur.num); cur = { num: K.mul(cur.num, q.num) }; } return rankQ(vs.map((v, k) => K.scale(v, q.den ** BigInt(d - 1 - k)))) === d; };
    let best = null;
    if (S.length) {
        for (const c of cusps.values()) {
            const trans = [], mult = [];
            for (const it of c.words) {
                const B = conjAt(c, it.M);
                if (it.parabolic) trans.push({ word: it.word, M: it.M });
                else mult.push({ v: K.divide(B[0], B[3]), word: it.word });
            }
            // the ℤ-rank of the translations: rank d (and O^× infinite) gives E(N·O) ⊆ hΓh⁻¹ as in the
            // S = ∅ case, so Γ ∩ SL₂(O) has finite index in SL₂(O) (Vaserstein); Γ is unbounded at
            // every prime of S and Zariski dense, so its closure there is open and unbounded, hence
            // contains PSL₂ (Howe–Moore), and Γ is S-arithmetic
            if (trans.length && unitsInfinite) {
                const tv = trans.slice(0, 600).map((t) => { const B = conjAt(c, t.M); return K.divide(B[1], B[3]).num; });
                const rk = rankQ(tv);
                if (rk === d) {
                    const ms = Date.now() - t0;
                    return { found: true, d, rank: d, S: S.map((pl) => `${pl.p}`), cusp: c.key, parabolic: trans[0].word, other: null, byTranslations: true, trans: trans.length, mult: mult.length, collisions: c.collisions || 0, elements: elements.length, cusps: cusps.size, ms };
                }
                if (!best || rk > (best.transRank || 0)) best = { ...(best || {}), transRank: rk };
            }
            if (!trans.length || !mult.length) { if (!best || !best.cusp) best = { ...(best || {}), rank: 0, cusp: c.key, trans: trans.length, mult: mult.length, covered: 0 }; continue; }
            const covered = S.map(() => null);
            let gen = null;
            for (const m of mult.slice(0, 300)) {
                if (!gen && generatesK(m.v)) gen = m;
                S.forEach((pl, i) => { if (!covered[i] && ring.val(m.v, pl.pr) !== 0) covered[i] = m; });
                if (gen && covered.every(Boolean)) break;
            }
            const nCov = covered.filter(Boolean).length;
            if (!best || nCov + (gen ? 1 : 0) > best.covered + (best.gen ? 1 : 0)) best = { rank: gen ? d : 0, cusp: c.key, parabolic: trans[0].word, other: gen ? gen.word : null, trans: trans.length, mult: mult.length, covered: nCov, gen: !!gen };
            if (gen && covered.every(Boolean)) {
                const ms = Date.now() - t0;
                return { found: true, d, rank: d, S: S.map((pl) => `${pl.p}`), cusp: c.key, parabolic: trans[0].word, other: gen.word, covering: covered.map((m) => m.word), trans: trans.length, mult: mult.length, elements: elements.length, cusps: cusps.size, ms };
            }
        }
        const ms = Date.now() - t0;
        return { found: false, S: S.map((pl) => `${pl.p}`), reason: best ? `at the best cusp, ${best.trans} translations and ${best.mult} multipliers: ${best.gen ? 'one generates K' : 'none generates K'}, ${best.covered} of ${S.length} primes of S covered` : 'no cusp', elements: elements.length, cusps: cusps.size, best, ms };
    }
    for (const c of cusps.values()) {
        const trans = [], mult = [];
        for (const it of c.words) {
            const B = conjAt(c, it.M);                 // upper triangular (a′ b′; 0 d′)
            if (it.parabolic) { const q = K.divide(B[1], B[3]); trans.push({ v: q, word: it.word }); }
            else { const q = K.divide(B[0], B[3]); mult.push({ v: q, word: it.word }); }
        }
        if (!trans.length) continue;
        // vectors αᵏ·τ (k < d) for every α, and the τ themselves, as integer vectors (denominators cleared)
        const vecs = [];
        const asInt = (q) => q.num;
        for (const t of trans.slice(0, 40)) {
            vecs.push(asInt(t.v));
            for (const m of mult.slice(0, 6)) {
                let cur = { num: t.v.num, den: t.v.den };
                for (let k = 1; k < d; k++) { cur = { num: K.mul(cur.num, m.v.num), den: cur.den * m.v.den }; vecs.push(cur.num); }
            }
        }
        const rank = rankQ(vecs);
        if (!best || rank > best.rank) best = { rank, cusp: c.key, parabolic: trans[0].word, other: mult.length ? mult[0].word : null, trans: trans.length, mult: mult.length };
        if (rank === d) break;
    }
    const ms = Date.now() - t0;
    if (best && best.rank === d) return { found: true, d, S: [], ...best, elements: elements.length, cusps: cusps.size, ms };
    return { found: false, S: [], reason: best ? `the unipotents at the cusps found have rank ${best.rank} < ${d}` : 'no cusp with a translation', elements: elements.length, cusps: cusps.size, best, ms };
}
